// A device is only 'Connected' if it said so RECENTLY. global.Status holds
// the last decoded status with no expiry, so a device that stopped being
// polled (blacklisted, or its whole RS-485 segment down) would otherwise
// keep showing its last good value indefinitely. 60s is comfortably longer
// than any configured poll interval, so a live device never flickers.
var STALE_MS = 60000;
var statusTs = global.get('StatusTs') || {};
var nowMs = Date.now();
function statusFor(sid) {
    var st = global.get('Status[' + sid + ']');
    var ts = statusTs[sid];
    if (!ts || (nowMs - ts) > STALE_MS) return 'No Data';
    return st;
}
