/******************************************************************
 * BusbarTherMo™ – Process Logic (ZONE ENABLED)
 ******************************************************************/

const JOINT_MASTER_KEY = "joint_master_zone_A";
const CONFIG_KEY = "busbartherm_system_config";
const AMBIENT_STATE_KEY = "latest_ambient_state";

const DT_MIN_SEC = 0.5;
const DT_MAX_SEC = 300;
// Slice 10: an ambient reading older than this (s) is treated as missing so
// the resolver falls back (zone/panel median) instead of using a stale value.
const AMBIENT_MAX_AGE_SEC = 60;


// -------------------------------------------------
function safeFixed(v, d) {
    return Number.isFinite(v) ? Number(v.toFixed(d)) : null;
}


// -------------------------------------------------
// INPUT VALIDATION
// -------------------------------------------------
const sensor = msg.payload;
if (!sensor || typeof sensor.id !== "number" || typeof sensor.val !== "number") {
    return [null, null, null];
}

const sensorID = sensor.id;
const sensorVal = sensor.val;
const nowMs = Date.now();


// -------------------------------------------------
// SENSOR STATUS
// -------------------------------------------------
let sensor_status = sensor.st ?? "OK";

if (sensor.st === "err") sensor_status = "Communication_Error";
else if (sensorVal > 300) sensor_status = "Sensor_Error";

const freeze =
    sensor_status === "Communication_Error" ||
    sensor_status === "Sensor_Error";


// -------------------------------------------------
// LOAD JOINT MASTER
// -------------------------------------------------
const joints = global.get(JOINT_MASTER_KEY) || [];
if (!Array.isArray(joints)) return [null, null, null];


// ✅ AMBIENT SET
const ambientSet = new Set(
    joints.map(j => j.ambientSlaveID).filter(id => id != null)
);

//node.warn(ambientSet)
// -------------------------------------------------
// AMBIENT CACHE
// -------------------------------------------------
let ambientState = global.get(AMBIENT_STATE_KEY) || {};

const isTrueAmbient = ambientSet.has(sensorID);

if (isTrueAmbient) {

    const _prevAmb = ambientState[sensorID] || {};
    const lastMs = _prevAmb.lastTsMs;

    let dt = Number.isFinite(lastMs) ? (nowMs - lastMs)/1000 : null;

    if (dt !== null) {
        dt = Math.max(DT_MIN_SEC, Math.min(DT_MAX_SEC, dt));
    }

    // A failed/faulted ambient read must NOT overwrite the last good value
    // (a dead sensor commonly reads a plausible 0). Keep the last good val and
    // freeze lastGoodTsMs so staleness is detectable downstream; record status
    // so the resolver can reject a faulted ambient outright.
    const _ambGood = !freeze;
    ambientState[sensorID] = {
        val: _ambGood ? sensorVal : _prevAmb.val,
        status: _ambGood ? "OK" : sensor_status,
        lastTsMs: nowMs,
        lastGoodTsMs: _ambGood ? nowMs : _prevAmb.lastGoodTsMs,
        sample_dt_sec: safeFixed(dt,3),
        timestamp: new Date(nowMs).toISOString()
    };

    global.set(AMBIENT_STATE_KEY, ambientState);
}


// -------------------------------------------------
// FIND JOINT
// -------------------------------------------------
const joint = joints.find(j => j.slaveID === sensorID);


// =================================================
// ✅ UNASSIGNED SENSOR (OUTPUT 3)
// =================================================
if (!joint && !isTrueAmbient) {

    msg.payload = {
        sensor_id: sensorID,
        val: sensorVal,
        sensor_status,

        type: "UNASSIGNED",

        zone_id: null,
        zone_name: "Unassigned",

        timestamp: new Date(nowMs).toISOString()
    };

    msg.topic = "unassigned";
    return [null, null, msg];
}

//node.warn([isTrueAmbient,joint])
// =================================================
// ✅ AMBIENT SENSOR (OUTPUT 2)
// =================================================
if (!joint && isTrueAmbient) {

    const sensorKey = `AMBIENT_${sensorID}`;

    msg.payload = {
        joint_id: sensorKey,
        joint_name: sensorKey,

        zone_id: "AMBIENT",
        zone_name: "Ambient",

        slaveID: sensorID,
        val: sensorVal,
        sensor_status,

        isAmbient: true,
        isProcessSensor: false,

        timestamp: new Date(nowMs).toISOString()
    };

    msg.topic = "ambient";
    return [null, msg, null];
}


// =================================================
// ✅ JOINT SENSOR (OUTPUT 1)
// =================================================

// -------------------------------------------------
// LOAD CONFIG
// -------------------------------------------------
const cfgWrap =
    global.get(CONFIG_KEY, "default") ||
    global.get(CONFIG_KEY);

const cfg = cfgWrap?.config ?? cfgWrap;
if (!cfg?.ror?.timeWindowMin) return [null, null, null];

const tauSec = cfg.ror.timeWindowMin * 60;


// -------------------------------------------------
// EMA STATE
// -------------------------------------------------
let emaState = context.get("emaState") || {};

// Slice 9 step 6: on restore from blacklist, reset this joint's EMA + deltaT
// baseline so the first fresh reading re-initialises (emaTemp = sensorVal,
// RoR = 0). Prevents a spurious rate after a long blackout with a big change.
const _blReset = global.get("busduct_ema_reset", "default") || {};
if (_blReset[joint.joint_id]) {
    delete emaState[joint.joint_id];
    const _dts = context.get("deltaTEmaState") || {};
    delete _dts[joint.joint_id];
    context.set("deltaTEmaState", _dts);
    delete _blReset[joint.joint_id];
    global.set("busduct_ema_reset", _blReset, "default");
}

emaState[joint.joint_id] ??= {
    emaTemp: sensorVal,
    lastTsMs: nowMs,
    lastRor: 0
};

let lastTsMs = emaState[joint.joint_id].lastTsMs ?? nowMs;

let dtSec = (nowMs - lastTsMs) / 1000;
dtSec = Math.max(DT_MIN_SEC, Math.min(DT_MAX_SEC, dtSec));

const alpha = Math.min(1, dtSec / tauSec);

let emaTemp = emaState[joint.joint_id].emaTemp;
let ror = emaState[joint.joint_id].lastRor;


// -------------------------------------------------
// EMA / ROR
// -------------------------------------------------
if (!freeze) {
    // Update EMA every sample: alpha = dtSec/tauSec already time-weights
    // the step, so a fast (sub-2s) sample just takes a correspondingly tiny
    // step. On the first sample emaTemp == sensorVal, so ror is naturally 0
    // - no sub-2s guard needed. The old "dtSec < 2" guard zeroed RoR (and
    // froze emaTemp) permanently on this panel's ~0.5s poll interval.
    emaTemp += alpha * (sensorVal - emaTemp);
    ror = (sensorVal - emaTemp) / tauSec * 3600;
}

emaState[joint.joint_id] = {
    emaTemp,
    lastTsMs: nowMs,
    lastRor: ror
};

context.set("emaState", emaState);


// -------------------------------------------------
// ΔT CALC
// -------------------------------------------------
let ambient = null;
let deltaT = null;

let deltaTEmaState = context.get("deltaTEmaState") || {};

if (joint.ambientSlaveID != null) {

    // Slice 10: effective ambient with outlier rejection + fallback
    // (configured -> zone median -> panel median). A single failed/drifting
    // ambient no longer poisons ΔT for every joint that references it.
    const _cs = global.get("busductConfigService");
    const _ambReadings = {};
    for (const _id in ambientState) {
        const _a = ambientState[_id];
        if (!_a || !Number.isFinite(_a.val)) continue;
        const _goodTs = Number.isFinite(_a.lastGoodTsMs) ? _a.lastGoodTsMs : _a.lastTsMs;
        _ambReadings[_id] = {
            val: _a.val,
            age_sec: Number.isFinite(_goodTs) ? (nowMs - _goodTs)/1000 : Infinity,
            status: _a.status || "OK"
        };
    }
    const _zoneOfAmb = {};
    for (const _j of joints) {
        if (_j.ambientSlaveID != null && _j.zone_id != null) _zoneOfAmb[_j.ambientSlaveID] = _j.zone_id;
    }
    const eff = (_cs && _cs.resolveAmbient)
        ? _cs.resolveAmbient({ configuredId: joint.ambientSlaveID, zoneId: joint.zone_id, readings: _ambReadings, zoneOf: _zoneOfAmb, maxAgeSec: AMBIENT_MAX_AGE_SEC })
        : { val: (ambientState[joint.ambientSlaveID] && ambientState[joint.ambientSlaveID].val), source: "configured", ambient_id: joint.ambientSlaveID, rejected: false };

    if (eff && Number.isFinite(eff.val)) {

        const _srcId = eff.ambient_id != null ? eff.ambient_id : joint.ambientSlaveID;
        const _srcAmb = ambientState[_srcId] || {};
        const ambLast = _srcAmb.lastTsMs ?? nowMs;
        const rawDT = sensorVal - eff.val;

        // AMBIENT RECOVERY: if the ambient reference was unusable on the previous
        // sample, this joint's ΔT EMA was built against a different (or absent)
        // reference. Decaying from it would take a full tau (timeWindowMin, e.g.
        // 20 min) to reflect reality - a stale ΔT alarm looks permanently stuck.
        // Drop the baseline so it re-inits from the real reading, exactly like
        // the Slice 9 blacklist-restore EMA reset.
        if (deltaTEmaState[joint.joint_id] && deltaTEmaState[joint.joint_id].ambInvalid) {
            delete deltaTEmaState[joint.joint_id];
        }

        deltaTEmaState[joint.joint_id] ??= {
            emaDeltaT: rawDT,
            lastTsMs: nowMs
        };

        let emaDT = deltaTEmaState[joint.joint_id].emaDeltaT;

        if (!freeze) {
            let dt = (nowMs - deltaTEmaState[joint.joint_id].lastTsMs)/1000;
            dt = Math.max(DT_MIN_SEC, Math.min(DT_MAX_SEC, dt));
            const a = Math.min(1, dt / tauSec);
            emaDT += a * (rawDT - emaDT);
        }

        deltaTEmaState[joint.joint_id] = {
            emaDeltaT: emaDT,
            lastTsMs: nowMs
        };

        context.set("deltaTEmaState", deltaTEmaState);

        ambient = {
            slaveID: _srcId,
            val: eff.val,
            age_sec: safeFixed((nowMs - ambLast)/1000,1),
            source: eff.source
        };

        deltaT = {
            raw: safeFixed(rawDT,2),
            ema: safeFixed(emaDT,2)
        };
    } else {
        // No usable ambient -> ΔT is deliberately NOT computed (never fabricated
        // against 0). Mark the baseline invalid so it re-initialises the moment
        // the ambient recovers, instead of decaying from a poisoned value.
        deltaTEmaState[joint.joint_id] = { ambInvalid: true };
        context.set("deltaTEmaState", deltaTEmaState);
    }
}


// -------------------------------------------------
// ✅ FINAL OUTPUT (ZONE ENABLED)
// -------------------------------------------------
msg.payload = {

    joint_name: joint.joint_name,
    joint_id: joint.joint_id,

    // ✅ ZONE INCLUDED
    zone_id: joint.zone_id || "UNKNOWN",
    zone_name: joint.zone_name || "Unknown",

    slaveID: joint.slaveID,

    val: sensorVal,
    emaTemp: safeFixed(emaTemp,2),
    ror: safeFixed(ror,3),

    ambient,
    deltaT,

    sample_dt_sec: safeFixed(dtSec,3),
    timestamp: new Date(nowMs).toISOString(),
    sensor_status,

    isAmbient: false,
    isProcessSensor: true
};

msg.topic = "joint";

return [msg, null, null];

/******************************************************************
 * BusbarTherm – Alarm Manager (FINAL FULL SAFE VERSION)
 * ✅ ORIGINAL LOGIC PRESERVED 100%
 * ✅ FIXES:
