 *    - False alarms protection intact
 * ✅ ADDITIONS:
 *    - Readable raise email
 *    - Clear email + duration
 *    - Local time formatting (emails only)
 ******************************************************************/

const nowMs = Date.now();
const nowISO = new Date(nowMs).toISOString();

// ✅ LOCAL TIME (EMAIL ONLY)
function formatLocal(ts) {
  const d = new Date(ts);
  const pad = n => n.toString().padStart(2, "0");
  return `${pad(d.getDate())}-${pad(d.getMonth() + 1)}-${d.getFullYear()} ` +
    `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

// ✅ DURATION
function formatDuration(startISO, endISO) {
  // @ts-ignore
  const diffMs = new Date(endISO) - new Date(startISO);
  const sec = Math.floor(diffMs / 1000);
  const min = Math.floor(sec / 60);
  const hr = Math.floor(min / 60);
  return `${hr}h ${min % 60}m ${sec % 60}s`;
}

// -------------------------------------------------
// LOAD CONFIG
// -------------------------------------------------
const cfgWrap =
  global.get("busbartherm_system_config", "default") ||
  global.get("busbartherm_system_config");

const cfg = cfgWrap?.config ?? cfgWrap;
if (!cfg) return null;

// -------------------------------------------------
// ZONE SAFE EXTRACTION
// -------------------------------------------------
const d = msg.payload || {};

const zone_id = (d.zone_id != null) ? d.zone_id : "UNKNOWN";
const zone_name = (d.zone_name != null) ? d.zone_name : "Unknown";

// The operator names every joint in the Joint Config table (a mandatory column,
// stored as schema joints[].label - "Riser bend, above ACB-8"). ProcessLogic
// carries it through as d.joint_name, but until 2026-08-31 the alarm object kept
// only joint_id, so every alarm surface - the "Location" column, the e-mails, the
// cloud - said "J02" for a joint someone had given a real location to. Zone had
// both id and name all along; joint now matches.
// Null, not the id, when there is no name: consumers fall back themselves, and a
// fabricated name would be indistinguishable from a real one.
const joint_name = (d.joint_name != null && d.joint_name !== "") ? d.joint_name : null;

/** "J02 (Riser bend, above ACB-8)", or just "J02" when unnamed. For e-mail bodies. */
function jointLabel(a) {
  const id = a.joint_id ?? "SYSTEM";
  return (a.joint_name && a.joint_name !== id) ? `${id} (${a.joint_name})` : String(id);
}

// -------------------------------------------------
// STATES
// -------------------------------------------------
let activeAlarms = context.get("activeAlarms") || {};
let persistState = context.get("alarmPersistence") || {};
let emailSent = context.get("emailSentState") || {};
let historian = global.get("busbartherm.alarmHistorian", "default") || [];

let clearedNow = [];
let emails = [];

// =================================================
// CLEAR HISTORY
// =================================================
if (msg.payload?.action === "CLEAR_HISTORY") {
  historian = [];
  global.set("busbartherm.alarmHistorian", historian, "default");
  context.set("prevHistoryJSON", "");
  return [null, null, { payload: [] }, null];
}

if (msg.payload?.action === "BOOT_REFRESH") {

    return [
        { payload: Object.values(activeAlarms) },
        null,
        historian,
        null
    ];
}

// =================================================
// ACK (Active Alarms UI sends {action:"ACK", instanceId})
// =================================================
if (msg.payload?.action === "ACK" && msg.payload.instanceId) {
  const a = activeAlarms[msg.payload.instanceId];
  if (a && a.status === "ACTIVE_NACK") {
    a.status = "ACTIVE_ACK";
    a.ackTs = nowISO;
    a.ackBy = msg.payload.user || "UI";
    const h = historian.find(e => e.instanceId === a.instanceId && e.raisedTs === a.raisedTs);
    if (h && h !== a) { h.status = "ACTIVE_ACK"; h.ackTs = a.ackTs; h.ackBy = a.ackBy; }
    context.set("activeAlarms", activeAlarms);
    global.set("busbartherm.alarmHistorian", historian, "default");
  }
  return buildOutputs(activeAlarms, historian, [], []);
}
// =================================================
// CHANGE TRACKING
// =================================================
let prevActiveJSON = context.get("prevActiveJSON") || "";
let prevHistoryJSON = context.get("prevHistoryJSON") || "";

function buildOutputs(activeAlarms, historian, clearedNow, emails) {

  // Mirror active alarms to a global so the blacklist engine can tell a
  // held (STALE) joint from a merely OFFLINE one (Slice 9 step 5).
  global.set("busbartherm.activeAlarms", activeAlarms, "default");

  const activeArray = Object.values(activeAlarms);

  const currentActiveJSON = JSON.stringify(activeArray);
  const currentHistoryJSON = JSON.stringify(historian);

  const activeChanged = currentActiveJSON !== prevActiveJSON;
  const historyChanged = currentHistoryJSON !== prevHistoryJSON;

  if (activeChanged) context.set("prevActiveJSON", currentActiveJSON);
  if (historyChanged) context.set("prevHistoryJSON", currentHistoryJSON);

  return [
    activeChanged ? { payload: activeArray } : null,
    clearedNow.length ? { payload: clearedNow } : null,
    historyChanged ? { payload: historian } : null,
    emails.length ? { payload: emails } : null
  ];
}

// =================================================
// EVENT INJECTION (UNCHANGED)
// =================================================
if (msg.payload?.action === "INJECT_EVENT" && msg.payload.alarm) {

  const event = {
    ...msg.payload.alarm,
    zone_id: msg.payload.alarm.zone_id ?? zone_id,
    zone_name: msg.payload.alarm.zone_name ?? zone_name,
    status: "EVENT",
    raisedTs: nowISO,
    clearedTs: nowISO
  };

  historian.push(event);
  global.set("busbartherm.alarmHistorian", historian, "default");

  return buildOutputs(activeAlarms, historian, [], []);
}

// =================================================
// COMMUNICATION WATCHDOG ✅ FIXED
// =================================================
// One COMM alarm PER RS-485 segment (Slice 10 two-segment): a dead bus2
// Nano must be distinguishable from a dead bus1 one, and each must clear on
// its own. bus1 (and any panel with a single unlabelled bus) keeps the
// original key, so its alarm identity, history and ACK state are unchanged.
const _commBus = msg.payload?.busId;
const _commOtherBus = _commBus && _commBus !== "bus1";
const COMM_KEY = _commOtherBus
  ? `SYSTEM|${String(_commBus).toUpperCase()}|COMM_FAILURE`
  : "SYSTEM|MODULE|COMM_FAILURE";

if (msg.payload?.commTimeout === true) {

  if (!activeAlarms[COMM_KEY]) {
    activeAlarms[COMM_KEY] = {
      instanceId: COMM_KEY,
      category: "SYSTEM",
      joint_id: "SYSTEM",
      zone_id,
      zone_name,
      alarm_type: "COMM_MODULE",
      level: "CRITICAL",
      status: "ACTIVE_NACK",
      raisedTs: nowISO,
      description: _commOtherBus
        ? `No data received from the ${_commBus} communication module for 60 seconds`
        : "No data received from communication module for 60 seconds",
      kpi: { state: "No Data" }
    };

    emails.push({
      subject: `🚨 Active Alarm: ${COMM_KEY}`,
      meta: { instanceId: COMM_KEY, kind: 'RAISE', level: 'CRITICAL', description: `communication failure - zone ${zone_name}` },
      body: `COMM FAILURE\nZone: ${zone_name}\nRaised: ${formatLocal(nowISO)}`
    });
    emailSent[COMM_KEY] = true;
  }

  context.set("activeAlarms", activeAlarms);
  return buildOutputs(activeAlarms, historian, [], []);
}

// ✅ FIX: clear ONLY when false
if (msg.payload?.commTimeout === false) {

  if (activeAlarms[COMM_KEY]) {

  const a = activeAlarms[COMM_KEY];
  const cleared = { ...a, status: "CLEARED", clearedTs: nowISO };
  const duration = formatDuration(a.raisedTs, nowISO);

  historian.push(cleared);
  clearedNow.push(cleared);
  emails.push({
    subject: `✅ Communication Restored: ${COMM_KEY}`,
    meta: { instanceId: COMM_KEY, kind: 'CLEAR', level: a.level, description: 'communication restored' },
    body: `
            Communication restored successfully

            Zone: ${a.zone_name}
            Alarm Type: ${a.alarm_type}
            Level: ${a.level}

            Raised: ${formatLocal(a.raisedTs)}
            Restored: ${formatLocal(nowISO)}
            Duration: ${duration}

            Description:
            ${a.description}
            `
    });
  delete activeAlarms[COMM_KEY];
  delete emailSent[COMM_KEY];
  delete persistState[COMM_KEY];
  }

  // "Data is flowing" carries no sensor reading, so stop here rather than
  // falling through into the process-alarm evaluation below.
  context.set("activeAlarms", activeAlarms);
  return buildOutputs(activeAlarms, historian, clearedNow, emails);
}

// =================================================
// DEVICE BLACKLIST (Slice 9) - one ACK-able SYSTEM alarm per blacklisted slave
// (mirrors the COMM watchdog: raise on blacklist, clear on restore)
// =================================================
if (msg.payload?.blacklist && msg.payload.blacklist.slave_id) {
  const b = msg.payload.blacklist;
  const BKEY = `SYSTEM|${b.slave_id}|BLACKLIST`;

  if (b.action === "raise") {
    if (!activeAlarms[BKEY]) {
      activeAlarms[BKEY] = {
        instanceId: BKEY,
        category: "SYSTEM",
        joint_id: "SYSTEM",
        zone_id,
        zone_name,
        alarm_type: "DEVICE_BLACKLIST",
        level: "CRITICAL",
        status: "ACTIVE_NACK",
        raisedTs: nowISO,
        slave_id: b.slave_id,
        affected_joints: b.joints || [],
        description: b.description || `Slave ${b.slave_id} blacklisted`,
        kpi: { state: "Not Measurable" }
      };
      emails.push({
        subject: `🚨 Active Alarm: ${BKEY}`,
        meta: { instanceId: BKEY, kind: 'RAISE', level: activeAlarms[BKEY].level, deviceLabel: activeAlarms[BKEY].device_label, description: activeAlarms[BKEY].description },
        body: `${activeAlarms[BKEY].description}\nRaised: ${formatLocal(nowISO)}`
      });
      emailSent[BKEY] = true;
    }
    context.set("activeAlarms", activeAlarms);
    return buildOutputs(activeAlarms, historian, [], emails);
  }

  if (b.action === "clear" && activeAlarms[BKEY]) {
    const a = activeAlarms[BKEY];
    const cleared = { ...a, status: "CLEARED", clearedTs: nowISO };
    historian.push(cleared);
    clearedNow.push(cleared);
    delete activeAlarms[BKEY];
    delete emailSent[BKEY];
    delete persistState[BKEY];
    // Step 6: restart persistence timers for the restored joints so a
    // re-appearing condition must re-prove itself from zero on fresh data.
    (b.joints || []).forEach(jid => {
      Object.keys(persistState).forEach(k => { if (k.startsWith(`PROCESS|${jid}|`)) delete persistState[k]; });
    });
    context.set("alarmPersistence", persistState);
    emails.push({
      subject: `✅ Alarm Cleared: ${BKEY}`,
      meta: { instanceId: BKEY, kind: 'CLEAR', level: b.level, deviceLabel: b.device_label, description: `device ${b.slave_id} restored` },
      body: `Device ${b.slave_id} restored\nCleared: ${formatLocal(nowISO)}`
    });
    context.set("activeAlarms", activeAlarms);
    return buildOutputs(activeAlarms, historian, clearedNow, emails);
  }

  return buildOutputs(activeAlarms, historian, [], []);
}

// =================================================
// PI POWER / THROTTLING (2026-07-29) - one ACK-able SYSTEM alarm.
// The Nano "hang" chased for a week was Pi under-voltage; the signal existed
// (vcgencmd get_throttled) but only in the cloud heartbeat. Surface it locally.
// =================================================
if (msg.payload?.powerHealth && msg.payload.powerHealth.key) {
  const p = msg.payload.powerHealth;
  const PKEY = p.key;

  if (p.action === "raise") {
    // Re-raise on escalation (WARNING -> CRITICAL) by replacing the entry.
    if (!activeAlarms[PKEY] || activeAlarms[PKEY].level !== p.level) {
      activeAlarms[PKEY] = {
        instanceId: PKEY,
        category: "SYSTEM",
        joint_id: "SYSTEM",
        zone_id,
        zone_name,
        alarm_type: "PI_POWER",
        level: p.level || "CRITICAL",
        status: "ACTIVE_NACK",
        raisedTs: nowISO,
        description: p.description || "Raspberry Pi power fault",
        kpi: { state: p.under_voltage ? "Under-voltage" : "Throttled" }
      };
      emails.push({
        subject: `\u26a0\ufe0f Active Alarm: ${PKEY}`,
        meta: { instanceId: PKEY, kind: 'RAISE', level: activeAlarms[PKEY].level, description: activeAlarms[PKEY].description },
        body: `${activeAlarms[PKEY].description}\nRaised: ${formatLocal(nowISO)}`
      });
      emailSent[PKEY] = true;
    }
    context.set("activeAlarms", activeAlarms);
    return buildOutputs(activeAlarms, historian, [], emails);
  }

  if (p.action === "clear" && activeAlarms[PKEY]) {
    const a = activeAlarms[PKEY];
    const cleared = { ...a, status: "CLEARED", clearedTs: nowISO };
    historian.push(cleared);
    clearedNow.push(cleared);
    delete activeAlarms[PKEY];
    delete emailSent[PKEY];
    delete persistState[PKEY];
    emails.push({
      subject: `\u2705 Alarm Cleared: ${PKEY}`,
      meta: { instanceId: PKEY, kind: 'CLEAR', level: p.level, description: p.description || 'Pi power normal' },
      body: `${p.description || "Pi power normal"}\nCleared: ${formatLocal(nowISO)}`
    });
    context.set("activeAlarms", activeAlarms);
    return buildOutputs(activeAlarms, historian, clearedNow, emails);
  }

  return buildOutputs(activeAlarms, historian, [], []);
}

// =================================================
// CLEANUP DELETED SENSORS (UNCHANGED + EMAIL)
// =================================================
// Source of truth is the APPLIED cfg/modbus+joints document, not the legacy
// joint_master_zone_A draft the dashboard edits - a draft can disagree with what
// is actually running. sweepDecommissionedAlarms also covers device-scoped
// SYSTEM alarms (a blacklist alarm for a DELETED slave could never clear, since
// a deleted device is never polled and so never emits `restored`), and refuses
// to sweep anything when the config cannot be read - the old `|| []` fallback
// would have auto-cleared every PROCESS alarm on the panel at once.
let __sweep = [];
try {
  const __cs = global.get('busductConfigService');
  if (__cs && __cs.alarmSweep) {
    const { doc: __doc } = __cs.createStore().readDomain('modbus_joints');
    __sweep = __cs.alarmSweep.sweepDecommissionedAlarms(activeAlarms, __doc);
  }
} catch (e) {
  node.warn('config sweep skipped: ' + e.message);   // never let it break alarming
}
const __sweepByKey = new Map(__sweep.map(s => [s.instanceId, s]));

for (let key in activeAlarms) {

  const alarm = activeAlarms[key];

  if (__sweepByKey.has(key)) {

    const duration = formatDuration(alarm.raisedTs, nowISO);

    const cleared = {
      ...alarm,
      status: "CLEARED",
      clearedTs: nowISO,
      reason: "CONFIG_REMOVED",
      description: alarm.description + " (Auto-cleared)"
    };

    historian.push(cleared);
    clearedNow.push(cleared);

    emails.push({
      subject: `✅ Auto Clear: ${alarm.instanceId}`,
      meta: { instanceId: alarm.instanceId, kind: 'CLEAR', level: alarm.level, description: 'sensor removed from configuration' },
      body: `
              Alarm automatically cleared

              Zone: ${alarm.zone_name}
              Joint: ${jointLabel(alarm)}
              Type: ${alarm.alarm_type}
              Level: ${alarm.level}

              Reason: Sensor removed from configuration

              Raised: ${formatLocal(alarm.raisedTs)}
              Cleared: ${formatLocal(nowISO)}
              Duration: ${duration}

              Description:
              ${alarm.description}
              `
    });

    delete activeAlarms[key];
    delete emailSent[key];
    delete persistState[key];
  }
}

// -------------------------------------------------
function isActive(key) {
  return activeAlarms[key]?.status?.startsWith("ACTIVE");
}

// ✅ RAISE EMAIL IMPROVED
function raiseAlarm(alarm) {

  alarm.zone_id = alarm.zone_id ?? zone_id;
  alarm.zone_name = alarm.zone_name ?? zone_name;
  // Defaulted here rather than in each builder, exactly as zone_name is: every
  // caller of raiseAlarm is joint-scoped and describes THIS message's joint.
  alarm.joint_name = alarm.joint_name ?? joint_name;

  activeAlarms[alarm.instanceId] = alarm;

  if (!emailSent[alarm.instanceId]) {

    emails.push({
      subject: `🚨 Active Alarm: ${alarm.instanceId}`,
      meta: { instanceId: alarm.instanceId, kind: 'RAISE', level: alarm.level, description: alarm.description },
      body: `
Zone: ${alarm.zone_name}
Joint: ${jointLabel(alarm)}
Type: ${alarm.alarm_type}
Level: ${alarm.level}
Raised: ${formatLocal(alarm.raisedTs)}

${alarm.description}
`
    });

    emailSent[alarm.instanceId] = true;
  }
}

// ✅ CLEAR EMAIL
function clearAlarm(key) {

  const a = activeAlarms[key];
  if (!a) return;

  const duration = formatDuration(a.raisedTs, nowISO);

  const cleared = {
    ...a,
    status: "CLEARED",
    clearedTs: nowISO
  };

  historian.push(cleared);
  clearedNow.push(cleared);

  emails.push({
    subject: `✅ Alarm Cleared: ${a.instanceId}`,
    meta: { instanceId: a.instanceId, kind: 'CLEAR', level: a.level, description: a.description },
    body: `
Alarm cleared successfully

Zone: ${a.zone_name}
Joint: ${jointLabel(a)}
Type: ${a.alarm_type}
Level: ${a.level}

Raised: ${formatLocal(a.raisedTs)}
Cleared: ${formatLocal(nowISO)}
Duration: ${duration}

Description:
${a.description}
`
  });

  delete activeAlarms[key];
  delete emailSent[key];
}

// =================================================
// SENSOR STATUS (UNCHANGED)
// =================================================
if (typeof d.sensor_status === "string") {

  const systemDefs = [
    { status: "Communication_Error", type: "COMMUNICATION", level: "CRITICAL", description: "Sensor communication failure" },
    { status: "Sensor_Error", type: "SENSOR_FAULT", level: "WARNING", description: "Sensor value out of valid range" }
  ];

  systemDefs.forEach(S => {
    const key = `SYSTEM|${d.joint_id}|${S.type}`;

    if (d.sensor_status === S.status) {
      if (!isActive(key)) raiseAlarm({
        instanceId: key,
        category: "SYSTEM",
        joint_id: d.joint_id,
        zone_id,
        zone_name,
        alarm_type: S.type,
        level: S.level,
        status: "ACTIVE_NACK",
        raisedTs: nowISO,
        description: S.description
      });
    } else {
      if (isActive(key)) clearAlarm(key);
    }
  });
}

// ✅ CRITICAL GUARD (DO NOT CHANGE)
if (d.sensor_status === "Communication_Error" || d.sensor_status === "Sensor_Error") {
  return buildOutputs(activeAlarms, historian, clearedNow, emails);
}

// =================================================
// PROCESS ENGINE (UNCHANGED)
// =================================================
function evaluateAlarm({ key, value, threshold, persistMin, build }) {

  persistState[key] ??= { raiseMs: null, clearMs: null };

  if (value >= threshold) {
    persistState[key].raiseMs ??= nowMs;
    persistState[key].clearMs = null;

    if ((nowMs - persistState[key].raiseMs) / 60000 >= persistMin) {
      if (!isActive(key)) raiseAlarm(build());
    }
  } else {
    persistState[key].clearMs ??= nowMs;
    persistState[key].raiseMs = null;

    if ((nowMs - persistState[key].clearMs) / 60000 >= persistMin) {
      if (isActive(key)) clearAlarm(key);
    }
  }
}

// =================================================
// ROR + DELTAT (UNCHANGED)
// =================================================
if (typeof d.ror === "number") {
  [
    { lvl: "CRITICAL", th: cfg.ror.critical, p: cfg.persistence.criticalMin },
    { lvl: "WARNING", th: cfg.ror.warning, p: cfg.persistence.warningMin },
    { lvl: "WATCH", th: cfg.ror.watch, p: cfg.persistence.watchMin }
  ].forEach(L => {

    const key = `PROCESS|${d.joint_id}|ROR|${L.lvl}`;

    evaluateAlarm({
      key,
      value: d.ror,
      threshold: L.th,
      persistMin: L.p,
      build: () => ({
        instanceId: key,
        category: "PROCESS",
        joint_id: d.joint_id,
        zone_id,
        zone_name,
        alarm_type: "ROR",
        level: L.lvl,
        status: "ACTIVE_NACK",
        raisedTs: nowISO,
        description: `RoR ${d.ror.toFixed(2)} ≥ ${L.th}`,
        value: d.ror,
        threshold: L.th,
        persistence_min: L.p,
        absolute_temp_c: d.val
      })
    });
  });
}

if (typeof d.deltaT?.ema === "number") {
  [
    { lvl: "CRITICAL", th: cfg.deltaT.critical, p: cfg.persistence.criticalMin },
    { lvl: "WARNING", th: cfg.deltaT.warning, p: cfg.persistence.warningMin },
    { lvl: "WATCH", th: cfg.deltaT.watch, p: cfg.persistence.watchMin }
  ].forEach(L => {

    const key = `PROCESS|${d.joint_id}|DELTA_T|${L.lvl}`;

    evaluateAlarm({
      key,
      value: d.deltaT.ema,
      threshold: L.th,
      persistMin: L.p,
      build: () => ({
        instanceId: key,
        category: "PROCESS",
        joint_id: d.joint_id,
        zone_id,
        zone_name,
        alarm_type: "DELTA_T",
        level: L.lvl,
        status: "ACTIVE_NACK",
        raisedTs: nowISO,
        description: `ΔT ${d.deltaT.ema.toFixed(2)} ≥ ${L.th}`,
        value: d.deltaT.ema,
        threshold: L.th,
        persistence_min: L.p,
        absolute_temp_c: d.val
      })
    });
  });
}

// =================================================
// CSV EMAIL (UNCHANGED)
// =================================================
function convertToCSV(data) {
  if (!data.length) return "";
  const headers = Object.keys(data[0]);
  const rows = data.map(obj =>
    headers.map(h => JSON.stringify(obj[h] ?? "")).join(",")
  );
  return [headers.join(","), ...rows].join("\n");
}

if (historian.length >= 100) {
  emails.push({
    subject: "BusbarTherm Alarm Batch (100 Events)",
    meta: { instanceId: 'SYSTEM|PANEL|ALARM_BATCH', kind: 'RAISE', level: 'INFO', description: 'alarm batch (100 events)' },
    attachments: [{
      filename: `alarm_history_${nowISO}.csv`,
      content: convertToCSV(historian)
    }]
  });

  historian.splice(0, 50);
}

// -------------------------------------------------
context.set("activeAlarms", activeAlarms);
//context.set("activeAlarms",{})
context.set("alarmPersistence", persistState);
context.set("emailSentState", emailSent);
global.set("busbartherm.alarmHistorian", historian, "default");

return buildOutputs(activeAlarms, historian, clearedNow, emails);

if(msg.payload.joint_id!= undefined)
{
    var sID=msg.payload.slaveID
    //node.warn(sID)
    var ror=msg.payload.ror
    var dT=msg.payload.deltaT.ema

    global.set('sensorRor['+sID+']',ror)
    global.set('sensordT['+sID+']',dT)
}

// The Alarm Manager hands us an ARRAY of queued emails on this tick.
//
// Two bugs lived in the three lines this replaces:
//  1. msg.topic was overwritten with a constant ("<project> Alerts"), throwing
//     away the per-alarm subject the Alarm Manager had already built - so every
//     alarm mail looked identical, and threaded into one endless conversation.
//  2. only data[0] was ever sent. Two joints crossing threshold in the same
//     tick, or a raise plus a clear, silently dropped all but the first. That
//     is precisely the moment mail matters.
const svc = global.get('busductConfigService');
const emails = Array.isArray(msg.payload) ? msg.payload : (msg.payload ? [msg.payload] : []);
if (!emails.length) return null;

const to = global.get('EmailID');
const projectName = (global.get('project_config') || {}).project_name || 'BusductTherMo';

// Site and panel identity come from the gateway's composition root - the one
// place that may read the edge config. Null on an unprovisioned panel, in which
// case the subject simply omits them rather than failing.
let siteId = null, panelId = null;
try {
  const gw = global.get('busductCloudGateway');
  const id = gw && gw.getGatewayInfo && gw.getGatewayInfo()?.identity;
  siteId = id?.site_id;
  panelId = id?.panel_id;
} catch (e) { /* identity is a nicety; never let it block an alarm mail */ }

if (!svc || !svc.alarmEmail) {
  // Fail LOUD but still deliver: an alarm mail must never be lost because a
  // library did not load. Falls back to the old constant subject.
  node.error('busductConfigService.alarmEmail not loaded - RESTART Node-RED (a Deploy does not re-require it)', msg);
  for (const e of emails) {
    node.send({ topic: projectName + ' Alerts', payload: e.body, to, attachments: e.attachments });
  }
  return null;
}

for (const e of emails) {
  node.send(svc.alarmEmail.toMailMessage(e, { projectName, siteId, panelId, to }));
}
node.status({ fill: 'blue', shape: 'dot', text: emails.length + ' mail(s) @ ' + new Date().toLocaleTimeString() });
return null;

if(msg.payload.joint_id=="J9")
{
    return msg;
}

/******************************************************************
 * COMM FAILURE RECOVERY CONTROLLER — per RS-485 segment
 *
 * Decisions live in src/config-service/bus-recovery.js (planRecovery);
 * this node is the wiring: current alarms in, USB power-cycles out.
 *
 * Each segment is its own Nano on its own USB port, so a wedged bus2
 * Nano is power-cycled without touching bus1's live polling. bus1 is
 * unchanged — same COMM alarm key, same RESET_n events, same exec node
 * with `-l 1-1` hardcoded. bus2's hub location is site wiring, so it
 * comes from the Node-RED environment (BUSDUCT_UHUBCTL_BUS2, e.g. 1-2);
 * unset means bus2 still raises its COMM alarm but is never cycled.
 *
 * Outputs: [0] bus1 exec  [1] Alarm Manager  [2] Email  [3] bus2 exec
 ******************************************************************/

const EXEC_OUTPUT = { bus1: 0, bus2: 3 };

// Keep the last full alarm list: the 5 s tick that drives the escalation
// ladder carries no payload of its own.
if (Array.isArray(msg.payload)) {
    context.set("lastAlarms", msg.payload);
}
const alarms = context.get("lastAlarms") || [];

const svc = global.get('busductConfigService');
if (!svc || !svc.planRecovery) {
    // functionGlobalContext is required once at Node-RED STARTUP; a plain
    // Deploy does not re-require it. Recovery is best-effort, so say it
    // loudly and stop rather than half-acting.
    node.error('busductConfigService.planRecovery not loaded - check settings.js and RESTART Node-RED (Deploy is not enough)');
    return [null, null, null, null];
}

const result = svc.planRecovery({
    alarms,
    states: context.get("states") || {},
    nowMs: Date.now(),
    // Hub spec per segment: LOCATION or LOCATION:PORT. bus1's location must be
    // declared here even though its exec node hardcodes it - it is what lets
    // planRecovery notice that cycling bus2 would also cut power to bus1.
    ports: {
        bus1: env.get('BUSDUCT_UHUBCTL_BUS1') || '1-1',
        bus2: env.get('BUSDUCT_UHUBCTL_BUS2') || null
    }
});

context.set("states", result.states);

for (const w of result.warnings) node.warn(w);
for (const e of result.errors) node.error(e);

const out = [[], [], [], []];

// busId rides along so the post-reboot resend (exec -> delay -> link out ->
// Send Nano Job) only re-sends THIS segment's job.
for (const r of result.resets) {
    out[EXEC_OUTPUT[r.busId]].push({ payload: r.port || "RESET", busId: r.busId });
}
for (const a of result.alarmEvents) {
    out[1].push({ payload: { action: "INJECT_EVENT", alarm: a } });
}
for (const m of result.emails) {
    out[2].push({ payload: m });
}

node.status({
    fill: result.resets.length ? "yellow" : "green",
    shape: "dot",
    text: result.resets.length
        ? "cycling " + result.resets.map(r => r.busId).join(", ")
        : "idle"
});

return out.map(list => (list.length ? list : null));

// ===============================
// CONFIG
// ===============================
const MAX_RECORDS = 400;
const TIMEOUT = 15000;

// ===============================
// GET STORED DATA
// ===============================
let history = global.get("busbartherm.alarmHistorian", "default") || [];
let sessions = flow.get("active_sessions") || {};

let now = Date.now();

// ===============================
// ✅ ZONE NORMALIZATION (NEW)
// ===============================
function normalizeZone(a) {
    return {
        ...a,
        zone_id: (a.zone_id !== undefined && a.zone_id !== null) ? a.zone_id : "UNKNOWN",
        zone_name: (a.zone_name !== undefined && a.zone_name !== null) ? a.zone_name : "Unknown"
    };
}


// ===============================
// 1. HANDLE UI EVENTS
// ===============================
if (msg.ui === "alarm_history" && msg.socketid) {

    const sid = msg.socketid;

    if (msg.event === "open" || msg.event === "heartbeat") {
        sessions[sid] = now;
    }

    if (msg.event === "close") {
        delete sessions[sid];
    }

    // cleanup stale
    for (let id in sessions) {
        if ((now - sessions[id]) > TIMEOUT) {
            delete sessions[id];
        }
    }

    flow.set("active_sessions", sessions);

    let activeCount = Object.keys(sessions).length;

    node.status({
        fill: activeCount > 0 ? "green" : "grey",
        shape: "dot",
        text: `Users: ${activeCount} | Alarms: ${history.length}`
    });

    // ✅ send normalized data
    if (msg.event === "open") {

        let output = history
            .slice(-MAX_RECORDS)
            .reverse()
            .map(normalizeZone);

        msg.payload = output;

        return msg;
    }

    return null;
}


// ===============================
// 2. HANDLE SYNC FROM ALARM MANAGER
// ===============================
if (Array.isArray(msg.payload)) {

    // ✅ normalize before storing
    history = msg.payload.map(normalizeZone);

    if (history.length > MAX_RECORDS) {
        history = history.slice(-MAX_RECORDS);
    }

    global.set("busbartherm.alarmHistorian", history, "default");

    let activeCount = Object.keys(sessions).length;

    node.status({
        fill: "blue",
        shape: "ring",
        text: `Synced: ${history.length} | Users: ${activeCount}`
    });

    if (activeCount > 0) {
        msg.payload = history.slice(-MAX_RECORDS).reverse();
        return msg;
    }

    return null;
}


// ===============================
// 3. IDLE STATUS
// ===============================
let activeCount = Object.keys(sessions).length;

node.status({
    fill: activeCount > 0 ? "green" : "grey",
    shape: "ring",
    text: `Idle | Users: ${activeCount} | Alarms: ${history.length}`
});

return null;

const TIMEOUT = 15000;

// ------------------------------------------------
// CACHE
// ------------------------------------------------
let active = global.get("active_alarms") || {};
let sessions = flow.get("active_alarm_sessions") || {};
//node.warn(active)
let now = Date.now();


// =================================================
// ✅ UI SESSION HANDLING
// =================================================
if (msg.ui === "active_alarm" && msg.socketid) {

    const sid = msg.socketid;

    if (msg.event === "open" || msg.event === "heartbeat") {
        sessions[sid] = now;
    }

    if (msg.event === "close") {
        delete sessions[sid];
    }

    // cleanup inactive
    for (let id in sessions) {
        if (now - sessions[id] > TIMEOUT) {
            delete sessions[id];
        }
    }

    flow.set("active_alarm_sessions", sessions);

    let userCount = Object.keys(sessions).length;

    node.status({
        fill: userCount ? "green" : "grey",
        shape: "dot",
        text: `Users: ${userCount} | Active: ${Object.keys(active).length}`
    });

    // send full state on open
    if (msg.event === "open") {
        msg.payload = Object.values(active);
        return msg;
    }

    return null;
}

// ===============================
// ACK REQUEST FROM UI
// ===============================
if (
    msg.payload &&
    msg.payload.action === "ACK" &&
    msg.payload.instanceId
) {
    let id = msg.payload.instanceId;

    if (active[id]) {

        active[id].status = "ACTIVE_ACK";
        active[id].ackTs = Date.now();

        global.set("active_alarms", active);

        // Update all connected dashboards immediately
        return {
            payload: Object.values(active)
        };
    }

    return null;
}

// =================================================
// ✅ VALIDATE INPUT
// =================================================
if (!Array.isArray(msg.payload)) return null;


// =================================================
// ✅ BUILD NEW ACTIVE MAP
// =================================================
let incoming = {};

msg.payload.forEach(a => {

    if (!a || !a.instanceId) return;

    // ✅ ✅ ✅ ZONE FIX (STRICT — DO NOT OVERRIDE VALID VALUES)
    if (a.zone_name === undefined) a.zone_name = "Unknown";
    if (a.zone_id === undefined) a.zone_id = "UNKNOWN";

    if (a.status === "ACTIVE_NACK" || a.status === "ACTIVE_ACK") {
        incoming[a.instanceId] = { ...a };  // clone for safety
    }
