//     "&to=" + msg.enddate


msg.payload = "/d/adtgftf/main-dashboard?orgId=1&viewPanel=panel-2&kiosk=true"+
    "&refresh=30s" +
    "&from=" + msg.fromdate +
    "&to=" + msg.enddate


return msg;

var data = msg.payload
node.warn(data)
msg.payload={}
msg.payload.alarmCount=data.length
//msg.payload.alarmCount=2

return msg;

if(msg.payload.tab=="Home")
{
    return msg;
}

let rows = msg.payload;

if (!Array.isArray(rows)) {
    msg.payload = { labels: [], datasets: [] };
    return msg;
}

let selectedSlave = flow.get("selectedSlave");
if (!selectedSlave) {
    msg.payload = { labels: [], datasets: [] };
    return msg;
}

let dailyCount = {};

rows.forEach(r => {
    if (!r || !r.Status || !r.Slave || !r.Date) return;
    if (selectedSlave !== "All" && String(r.Slave).trim() !== selectedSlave) return;

    let status = String(r.Status).trim().toLowerCase();
    if (status !== "disconnected" && status !== "disonnected") return;

    let date = String(r.Date).trim();
    dailyCount[date] = (dailyCount[date] || 0) + 1;
});

// Sort dates
let dates = Object.keys(dailyCount).sort((a, b) => {
    const [da, ma, ya] = a.split("-").map(Number);
    const [db, mb, yb] = b.split("-").map(Number);
    // @ts-ignore
    return (new Date(ya, ma-1, da) - new Date(yb, mb-1, db));
});

msg.payload = {
    labels: dates,
    datasets: [{
        label: `Daily Disconnections – ${selectedSlave}`,
        data: dates.map(d => dailyCount[d]),
        backgroundColor: "#e67e22"
    }]
};

return msg;

/**
 * PURPOSE:
 * - Build dynamic Slave dropdown
 * - Include "All" option
 * - Include ONLY slaves that have at least one Disconnected entry
 * - Sort slaves in ASCENDING NUMERIC order (Slave 2 < Slave 10 < Slave 29)
 * - Uses msg.options (Node-RED Dashboard standard)
 */

let rows = msg.payload;

// ---------- SAFETY ----------
if (!Array.isArray(rows)) {
    node.warn("CSV payload is not an array");
    msg.options = ["All"];
    return msg;
}

// Collect slaves with disconnections
let slaveSet = new Set();

rows.forEach(r => {
    if (!r || !r.Status || !r.Slave) return;

    let status = String(r.Status).trim().toLowerCase();

    if (status === "disconnected" || status === "disonnected") {
        let slave = String(r.Slave).trim();
        if (slave) slaveSet.add(slave);
    }
});

// ---------- SORT NUMERICALLY ----------
let sortedSlaves = Array.from(slaveSet).sort((a, b) => {
    // Extract numbers from "Slave XX"
    let na = parseInt(a.replace(/\D+/g, ""), 10);
    let nb = parseInt(b.replace(/\D+/g, ""), 10);

    // Fallback for safety
    if (isNaN(na)) return a.localeCompare(b);
    if (isNaN(nb)) return a.localeCompare(b);

    return na - nb;
});

// ---------- BUILD DROPDOWN OPTIONS ----------
msg.options = [
    "All",
    ...sortedSlaves
];

return msg;

if (!msg.payload) return null;

flow.set("selectedSlave", String(msg.payload).trim());

// Trigger re-read of CSV
return msg;

// Decide which page & password
if (msg.topic === 'alarm') {
    flow.set('req_type','alarm');
    flow.set('req_tab','Alarm Config');
    flow.set('auth_err','');
}
if (msg.topic === 'slave') {
    flow.set('req_type','system');
    flow.set('req_tab','Slave Config');
    flow.set('auth_err','');
}
if (msg.topic === 'joint') {
    flow.set('req_type','system');
    flow.set('req_tab','Joint Config');
    flow.set('auth_err','');
}
if (msg.topic === 'Disc') {
    flow.set('req_type','alarm');
    flow.set('req_tab','Connection Analytics');
    flow.set('auth_err','');
}
if (msg.topic === 'comm') {
    flow.set('req_type','system');
    flow.set('req_tab','Settings1');
    flow.set('auth_err','');
}
if (msg.topic === 'alert') {
    flow.set('req_type','alarm');
    flow.set('req_tab','Notification');
    flow.set('auth_err','');
}
msg.payload = { tab: 'Password' };
return msg;

// Access PINs come from the Node-RED environment, NOT the flow export.
// Set BUSDUCT_PW_SYSTEM / BUSDUCT_PW_ALARM on the Pi (see docs/security-hardening.md).
// Unset => empty => fail closed (no access).
const SYSTEM = env.get('BUSDUCT_PW_SYSTEM') || '';
const ALARM  = env.get('BUSDUCT_PW_ALARM')  || '';

let type=flow.get('req_type');
let tab=flow.get('req_tab');

if((type==='system' && SYSTEM && msg.payload===SYSTEM) || (type==='alarm' && ALARM && msg.payload===ALARM)){
    flow.set('auth_err','');
    msg.payload = { tab: tab };
    return msg;
}

flow.set('auth_err','❌ Wrong password');
return null;

const { createStore, buildNanoJobMessage } = global.get('busductConfigService');

// WHICH RS-485 SEGMENT THIS PIPELINE SERVES.
// A literal, not env.get(): function nodes have no per-node environment - env
// resolves from the enclosing group, then the tab - and both Send Nano Job
// nodes live on this same tab, so an env var could never differ between them.
const MY_BUS = 'bus1';

if (msg.busId && msg.busId !== MY_BUS) {
  return null;   // a resend addressed to the other segment's Nano
}

const store = createStore();
const excludeSlaveIds = global.get('busduct_blacklist_exclude') || [];   // Slice 9
const result = buildNanoJobMessage(store, { excludeSlaveIds, busId: MY_BUS });
if (result.error) {
  node.warn('Nano job compile failed for ' + MY_BUS + ': ' + result.error);
  node.status({ fill: 'red', shape: 'ring', text: MY_BUS + ': ' + result.error });
  return null;
}
node.status({ fill: 'green', shape: 'dot', text: MY_BUS + ': ' + result.job.read[0] + ' slave(s) @ ' + new Date().toLocaleTimeString() });
msg.payload = result.job;
return msg;

const svc = global.get('busductConfigService');
if (!svc) {
  // functionGlobalContext is loaded once at Node-RED STARTUP - a plain Deploy
  // does not re-require it. Say so on the page instead of returning nothing.
  node.error('busductConfigService is not in functionGlobalContext - check settings.js and RESTART Node-RED (Deploy is not enough)', msg);
  return [{ ...msg, payload: { error: 'Config service not loaded. Check settings.js functionGlobalContext, then restart Node-RED (not just Deploy).' } }, null, null];
}
const { createStore, handleModbusSettingsMessage, writeLegacyModbusGlobals, appendLegacyAudit } = svc;

try {
  const store = createStore();

  const draft = global.get('modbus_settings_draft') || null;
  const legacySlaveList = global.get('SlaveIDList') || [];
  const user = msg.payload?.user || 'UI';

  const { msg: outMsg, draft: newDraft, resendNeeded, resendBusIds, legacy, audit } =
    handleModbusSettingsMessage(msg, { store, draft, legacySlaveList, user });

  if (newDraft !== null) {
    global.set('modbus_settings_draft', newDraft);
  }
  if (legacy) {
    writeLegacyModbusGlobals(global, legacy);
  }
  if (audit) {
    appendLegacyAudit(global, 'joint_config_audit_log', audit);
  }

  // One resend message PER CHANGED BUS: each RS-485 segment is a separate Nano
  // with its own job, and the firmware re-inits its Modbus timeout on every job
  // update - so a bus2-only edit must not glitch bus1's live polling.
  const resendMsgs = (resendBusIds || (resendNeeded ? ['bus1'] : []))
    .map((busId) => ({ payload: 'apply', busId }));

  return [outMsg, resendMsgs.length ? resendMsgs : null, legacy ? { payload: legacy.paraRaw } : null];
} catch (e) {
  // Never fail silently: an exception here used to leave the dashboard table
  // blank with no clue whether the config was missing or the code had thrown.
  node.error('Modbus Settings handler failed: ' + (e.stack || e.message), msg);
  return [{ ...msg, payload: { error: 'Modbus Settings failed: ' + e.message } }, null, null];
}

// The legacy job builders on this tab read flow.paraRaw; keep it in sync
// with what the new Modbus Settings table just applied, so even if a legacy
// trigger fires it sends the same job content the compiler would.
flow.set('paraRaw', msg.payload);
return null;

const { getGateway, ingestKpiTap } = global.get('busductCloudGateway');
ingestKpiTap(getGateway(), msg);
return null;

const { getGateway, ingestAlarmActiveTap } = global.get('busductCloudGateway');
ingestAlarmActiveTap(getGateway(), msg);
return null;

const { getGateway, ingestAlarmClearedTap } = global.get('busductCloudGateway');
ingestAlarmClearedTap(getGateway(), msg);
return null;

// 60s tick: the gateway decides when a telemetry batch is due, using its
// persisted runtime interval (default 10 min; settable locally or from the
// cloud via the Slice 7 remote config channel). Emits nothing off-cycle.
const { getGateway, flushIfDue } = global.get('busductCloudGateway');
const status = flushIfDue(getGateway());
if (!status) return null;
msg.payload = status;
return msg;

const { getGateway, sendHeartbeat } = global.get('busductCloudGateway');
const configService = global.get('busductConfigService');
const store = configService.createStore();
msg.payload = sendHeartbeat(getGateway(), {
  fwVersion: global.get('fwVersion') || 'unknown',
  configVersions: { ...store.getAppliedVersions('modbus_joints'), ...store.getAppliedVersions('alarms') },
});
return msg;

// EC-2: publish the panel's own device health so a fleet view can see whether
// the panel can still MEASURE, not just what it measured. Everything here is
// already computed for the HMI's Device Health tab - this only stops throwing
// it away. The publisher decides whether to send (on change, plus an hourly
// resync), so this tick can run often without costing messages.
const { getGateway, publishDeviceHealth } = global.get('busductCloudGateway');
const cs = global.get('busductConfigService');
if (!cs) { node.status({fill:'red',shape:'ring',text:'lib not loaded - RESTART Node-RED'}); return null; }
const { doc } = cs.createStore().readDomain('modbus_joints');
if (!doc) { node.status({fill:'grey',shape:'ring',text:'no applied config'}); return null; }

const state = global.get('busduct_blacklist_state', 'default') || {};
const summary = cs.blacklist.summarizeBlacklist(state, Date.now(), { doc });
// Per-segment liveness lives on the tracker (the flow's own silence watchdogs
// keep their stamp in FLOW context on modbusMaster_V2, which this tab cannot read).
const busSeen = cs.blacklist.getTracker().busSeen || {};
const power = global.get('busduct_power_health', 'default') || null;

msg.payload = publishDeviceHealth(getGateway(), { summary, doc, busSeen, power });
const c = msg.payload.counts;
node.status({
  fill: (c.joints_offline || c.devices_blacklisted) ? 'yellow' : 'green',
  shape: 'dot',
  text: `${c.joints_live}/${c.joints_total} live | ${msg.payload.buses.join(' ')} | ${msg.payload.device_health}`,
});
return msg;

const { getGateway, setupRemoteConfig } = global.get('busductCloudGateway');
msg.payload = setupRemoteConfig({ gateway: getGateway() });
return msg;

const { getGateway, drainRemoteConfig } = global.get('busductCloudGateway');
const configService = global.get('busductConfigService');
// runs in normal message context (fresh global) - context writes land reliably
const sends = drainRemoteConfig(getGateway(), configService, global);
for (const s of sends) node.send(s);
return null;

const hist = global.get('busductHistorian');
if (!hist || typeof hist.toInfluxPoints !== 'function') {
  node.status({fill:'red',shape:'ring',text:'busductHistorian NOT loaded - add to settings.js + RESTART Node-RED'});
  return null;
}
let points;
try { points = hist.toInfluxPoints(msg); }
catch (e) { node.status({fill:'red',shape:'ring',text:'toInfluxPoints: ' + e.message}); node.error(e, msg); return null; }
if (!points || points.length === 0) {
  const st = msg.payload && msg.payload.sensor_status;
  node.status({fill:'yellow',shape:'ring',text:'skipped ' + (msg.topic || '?') + (st ? ' (' + st + ')' : '')});
  return null;
}
node.status({fill:'green',shape:'dot',text:points.length + ' pt @ ' + new Date().toLocaleTimeString()});
msg.payload = points;   // influxdb batch node shape
return msg;

const h = global.get('busductHistorian');
if (!h || typeof h.buildTrendQuery !== 'function') {
  node.status({fill:'red',shape:'ring',text:'busductHistorian NOT loaded - RESTART Node-RED'});
  return null;
}
if (msg.topic === 'sensor') flow.set('trendSensor', msg.payload);
else if (msg.topic === 'range') flow.set('trendRange', msg.payload);
const sensor = flow.get('trendSensor');
const range = flow.get('trendRange') || h.DEFAULT_RANGE;
if (!sensor) { node.status({fill:'grey',shape:'ring',text:'pick a sensor'}); return null; }
msg.query = h.buildTrendQuery(sensor, range);
