const h = global.get('busductHistorian');
if (!h || typeof h.resultsToCharts !== 'function') {
  node.status({fill:'red',shape:'ring',text:'busductHistorian NOT loaded - RESTART Node-RED'});
  return null;
}
const range = msg.trendRange || h.DEFAULT_RANGE;
const rows = Array.isArray(msg.payload) ? msg.payload.length : 0;
const charts = h.resultsToCharts(msg.payload, range);
node.status({fill: rows ? 'green' : 'yellow',shape:'dot',text: rows + ' rows'});
return [ { payload: charts.temp }, { payload: charts.delta }, { payload: charts.ror } ];

const h = global.get('busductHistorian');
if (!h || typeof h.sensorOptionsFromTagValues !== 'function') {
  node.status({fill:'red',shape:'ring',text:'busductHistorian NOT loaded - RESTART Node-RED'});
  return null;
}
msg.options = h.sensorOptionsFromTagValues(msg.payload);
node.status({fill: msg.options.length ? 'green' : 'yellow',shape:'dot',text:msg.options.length + ' sensors'});
return msg;

const { getGateway, setupCertRotation } = global.get('busductCloudGateway');
msg.payload = setupCertRotation({ gateway: getGateway() });
return msg;

const { getGateway, drainCertRotation } = global.get('busductCloudGateway');
const configService = global.get('busductConfigService');
// async: each rotation reconnects the transport and waits for the broker
// to accept/reject the new cert. Runs in message context so the audit lands.
return drainCertRotation(getGateway(), configService, global).then((sends) => {
  for (const s of sends) node.send(s);
  return null;
});

// Kiosk exit PIN validated server-side (never sent to the browser).
const pin = env.get('BUSDUCT_KIOSK_PIN');
if (pin && msg.payload === pin) {
    return [{ payload: 'exit' }, null];        // out 1 -> exec (killall chromium)
}
return [null, { payload: { kioskError: pin ? 'Invalid PIN!' : 'Kiosk PIN not configured' } }]; // out 2 -> template

const cs = global.get('busductConfigService');
const bl = cs && cs.blacklist;
if (!bl || !cs) { node.status({fill:'red',shape:'ring',text:'lib not loaded - RESTART Node-RED'}); return null; }
const isResult = msg.payload && msg.payload.t === 'r';
const isTick = msg.topic === 'blacklist-tick';
if (!isResult && !isTick) return null;   // ignore write acks / boot text
const tracker = bl.getTracker();   // process-wide singleton (NOT flow context - it would be JSON-serialised and lose its methods)
const { doc } = cs.createStore().readDomain('modbus_joints');
if (!doc) return null;
const aa = global.get('busbartherm.activeAlarms','default') || {};
const activeAlarmJointIds = new Set(Object.values(aa)
  .filter(a => a && a.category !== 'SYSTEM' && (a.status === 'ACTIVE_NACK' || a.status === 'ACTIVE_ACK'))
  .map(a => a.joint_id));
const nowMs = Date.now();
const prevKey = tracker._prevExcludeKey;
// msg.bus_id is stamped by the per-segment tap on the serial-in edge (Slice 10
// two-segment). Absent on a single-bus panel, and on bus1 where it is not
// needed: unit addresses are unique panel-wide, so address alone resolves.
const ctx = { doc, nowMs, prevExcludeKey: prevKey, activeAlarmJointIds, busId: msg.bus_id };
const res = isResult ? bl.processReadResult(tracker, msg.payload, ctx) : bl.processTick(tracker, ctx);
tracker._prevExcludeKey = res.excludeKey;
if (res.emaResetJoints && res.emaResetJoints.length) {
  const rs = global.get('busduct_ema_reset', 'default') || {};
  for (const jid of res.emaResetJoints) rs[jid] = true;
  global.set('busduct_ema_reset', rs, 'default');   // ProcessLogic consumes on the next sample
}
if (res.events.length || isTick) {
  global.set('busduct_blacklist_state', { joints: res.jointStates, slaves: tracker.snapshot(), updatedTs: new Date(nowMs).toISOString() }, 'default');
}
if (res.resendNeeded) {
  global.set('busduct_blacklist_exclude', res.excludeSlaveIds);
  // One resend PER AFFECTED SEGMENT: each bus is its own Nano, and the
  // firmware re-inits its Modbus timeout on every job update, so a device
  // failing on bus2 must not glitch bus1's live polling.
  const buses = res.resendBusIds && res.resendBusIds.length ? res.resendBusIds : ['bus1'];
  node.send([buses.map((busId) => ({ payload: 'blacklist-resend', busId, excludeSlaveIds: res.excludeSlaveIds })), null]);
}
for (const cmd of res.alarms) node.send([null, { payload: { blacklist: cmd } }]);
const nbl = res.excludeSlaveIds.length;
node.status({fill: nbl ? 'yellow' : 'green', shape:'dot', text: nbl ? (nbl + ' blacklisted') : 'all live'});
return null;

// Put wrongly-excluded slaves back into the Nano scan.
//
// busduct_blacklist_exclude is written to the DEFAULT context store, which on
// the Pi is localfilesystem-backed, so it SURVIVES a restart. The tracker does
// not. The Blacklist Engine only rewrites that global when resendNeeded is
// true, and after a restart that computes to false (fresh tracker -> empty
// exclude set -> "no change"), so a stale list is never corrected.
//
// The symptom is silent: an excluded slave is never polled, so it produces
// neither an ok nor an err for the tracker to count. The tracker calls it
// active, the HMI says "all responding", and the device just goes quiet -
// Diagnostics ages it out to "No Data" with its last value frozen. It is also a
// deadlock: never polled means never able to fail or recover, so it can never
// leave that state on its own.
//
// Runs at 10s, BEFORE the 20s alarm reconcile, so the scan is repaired first
// and a genuinely dead device has re-failed its 3 reads by the time alarms are
// reconciled.
const cs = global.get('busductConfigService');
if (!cs || !cs.blacklist) { node.status({fill:'red',shape:'ring',text:'lib not loaded - RESTART Node-RED'}); return null; }
const { doc } = cs.createStore().readDomain('modbus_joints');
if (!doc) { node.status({fill:'grey',shape:'ring',text:'no applied config'}); return null; }

const persisted = global.get('busduct_blacklist_exclude') || [];
const res = cs.blacklist.reconcileExcludeSet(persisted, cs.blacklist.getTracker(), doc);
if (!res.removed.length) { node.status({fill:'green',shape:'dot',text:'exclude set consistent'}); return null; }

global.set('busduct_blacklist_exclude', res.excludeSlaveIds);
node.warn('Returning wrongly-excluded slave(s) to the scan: ' + res.removed.join(', '));
node.status({fill:'yellow',shape:'dot',text:res.removed.length + ' slave(s) back in scan'});
const buses = res.resendBusIds.length ? res.resendBusIds : ['bus1'];
node.send([buses.map((busId) => ({ payload: 'blacklist-resend', busId, excludeSlaveIds: res.excludeSlaveIds }))]);
return null;

// Clear blacklist alarms that outlived the tracker that raised them.
//
// The tracker is an in-memory singleton and is EMPTY after a Node-RED restart;
// the alarm lives in localfilesystem-backed context and SURVIVES one. A device
// blacklisted before a restart therefore never gets its 'restored' event, and
// its CRITICAL alarm stays active forever while the device polls normally.
//
// Runs ONCE at boot, 20s in - late enough that polling has resumed and a
// genuinely dead device has already failed its 3 reads and been re-blacklisted,
// so its alarm is correctly left alone.
const cs = global.get('busductConfigService');
if (!cs || !cs.blacklist) { node.status({fill:'red',shape:'ring',text:'lib not loaded - RESTART Node-RED'}); return null; }
const { doc } = cs.createStore().readDomain('modbus_joints');
const active = global.get('busbartherm.activeAlarms', 'default') || {};
const clears = cs.blacklist.reconcileBlacklistAlarms(active, cs.blacklist.getTracker(), doc);
if (!clears.length) { node.status({fill:'green',shape:'dot',text:'no stale blacklist alarms'}); return null; }
node.status({fill:'yellow',shape:'dot',text:clears.length + ' stale alarm(s) cleared'});
node.warn('Clearing stale blacklist alarm(s): ' + clears.map(c => c.slave_id).join(', '));
for (const cmd of clears) node.send({ payload: { blacklist: cmd } });
return null;

const cs = global.get('busductConfigService');
const state = global.get('busduct_blacklist_state','default') || {};
// Pass the applied cfg so each row can show the OPERATOR-facing unit address
// (e.g. "101 (AMBIENT_101)") rather than only the internal slave_id ("sl21").
let doc = null;
try { doc = cs && cs.createStore ? cs.createStore().readDomain('modbus_joints').doc : null; } catch (e) { doc = null; }
msg.payload = (cs && cs.blacklist)
  ? cs.blacklist.summarizeBlacklist(state, Date.now(), { doc })
  : { slaves: [], counts: { blacklisted: 0, probing: 0, stale: 0, offline: 0 }, staleJoints: [], offlineJoints: [], updatedTs: null };
msg.payload.power = global.get('busduct_power_health','default') || { supported: null, ok: null, text: 'power: not sampled yet' };
return msg;

// Local Pi power/throttling watch (2026-07-29). The Nano "hang" chased for a
// week was Pi UNDER-VOLTAGE; vcgencmd already exposed it but only the cloud
// heartbeat carried it. Raise a local SYSTEM alarm + feed the Device Health tile.
const cg = global.get('busductCloudGateway');
if (!cg || !cg.derivePowerAlarm) { node.status({fill:'grey',shape:'ring',text:'gateway lib missing'}); return null; }

const health = cg.collectPiHealth();
const prev = flow.get('powerHealthState') || cg.initialPowerState();
const r = cg.derivePowerAlarm(health, prev);
flow.set('powerHealthState', r.state);

// Tile data for the Device Health dashboard (read by "Blacklist View").
global.set('busduct_power_health', { ...r.status, updatedTs: new Date().toISOString() }, 'default');

if (r.alarm) node.send({ payload: { powerHealth: r.alarm } });

node.status(
  r.status.supported === false ? {fill:'grey',shape:'ring',text:'power: n/a'}
  : r.status.ok ? {fill:'green',shape:'dot',text:'power OK'}
  : {fill:'red',shape:'dot',text:r.status.text}
);
return null;

const I = global.get('busductIntegration');
const cs = global.get('busductConfigService');
if (!I || !cs) { node.status({fill:'red',shape:'ring',text:'lib missing (settings.js)'}); return null; }
const svc = I.getBmsService(cs.createStore(), { serverFactory: I.jsmodbusServerFactory });
if (!svc) { node.status({fill:'grey',shape:'ring',text:'no cfg/integration applied'}); return null; }

// Register the BMS->alarm ACK bridge exactly once per PROCESS. getBmsService
// returns a module singleton that survives a Deploy (settings.js require()s the
// library at startup), so an unguarded onAck would stack a new handler on every
// deploy and ACK each alarm N times.
if (!svc._ackWired) {
  svc.onAck(function (cmd) {
    const active = global.get('busbartherm.activeAlarms', 'default') || {};
    Object.values(active)
      .filter(function (a) { return cmd.scope === 'all' || a.joint_id === cmd.joint_id; })
      .forEach(function (a) {
        // Same shape the HMI's Active Alarms table sends, so a BMS ACK takes the
        // identical path and lands in the audit trail attributed to the BMS.
        node.send({ payload: { action: 'ACK', instanceId: a.instanceId, user: 'BMS' } });
      });
  });
  svc._ackWired = true;
}

svc.start();
const m = svc.map;
node.status({fill: svc.slave ? 'green' : 'yellow', shape:'dot',
  text: (svc.slave ? 'serving' : 'image only (no jsmodbus)') + ' | tier ' + m.exposure_tier + ' | ' + m.extent + ' regs'});
return null;

const I = global.get('busductIntegration');
const cs = global.get('busductConfigService');
if (!I || !cs) { node.status({fill:'red',shape:'ring',text:'lib missing (settings.js)'}); return null; }
const svc = I.getBmsService(cs.createStore(), { serverFactory: I.jsmodbusServerFactory });
if (!svc) { node.status({fill:'grey',shape:'ring',text:'no cfg/integration applied'}); return null; }
svc.ingestJoint(msg.payload);
return null;

const I = global.get('busductIntegration');
const cs = global.get('busductConfigService');
if (!I || !cs) { node.status({fill:'red',shape:'ring',text:'lib missing (settings.js)'}); return null; }
const svc = I.getBmsService(cs.createStore(), { serverFactory: I.jsmodbusServerFactory });
if (!svc) { node.status({fill:'grey',shape:'ring',text:'no cfg/integration applied'}); return null; }
svc.ingestAlarmsActive(msg.payload);
return null;

const I = global.get('busductIntegration');
const cs = global.get('busductConfigService');
if (!I || !cs) { node.status({fill:'red',shape:'ring',text:'lib missing (settings.js)'}); return null; }
const svc = I.getBmsService(cs.createStore(), { serverFactory: I.jsmodbusServerFactory });
if (!svc) { node.status({fill:'grey',shape:'ring',text:'no cfg/integration applied'}); return null; }
// Blacklist state drives per-joint LIVE/STALE/OFFLINE + the DEGRADED health bit.
svc.ingestBlacklistState(global.get('busduct_blacklist_state', 'default') || {});
const r = svc.refresh();
node.status({fill:'green',shape:'dot',
  text:'hb ' + r.heartbeat + ' | lvl ' + r.rollup.highest_level + ' | live ' + r.rollup.live_joint_count});
return { payload: { heartbeat: r.heartbeat, highest_level: r.rollup.highest_level,
  active_alarms: r.rollup.active_alarm_count, live_joints: r.rollup.live_joint_count,
  worst_joint: r.rollup.worst_joint_id, registers: r.map.extent, serving: !!svc.slave } };

const I = global.get('busductIntegration');
const cs = global.get('busductConfigService');
if (!I || !cs) { node.status({fill:'red',shape:'ring',text:'lib missing'}); return null; }
const svc = I.getBmsService(cs.createStore(), { serverFactory: I.jsmodbusServerFactory });
if (!svc) {
  node.status({fill:'grey',shape:'ring',text:'no cfg/integration'});
  msg.payload = { rows: [], extent: 0, note: 'no cfg/integration applied - run tools/apply-integration-config.js' };
  return msg;
}

// snapshot() recomputes the image WITHOUT advancing the heartbeat or writing to
// the slave - a diagnostic view must not perturb the liveness signal the BMS
// depends on, nor push anything to a live gateway.
const s = svc.snapshot();
msg.payload = I.describeImage(s.map, s.image, {});
msg.payload.serving = !!svc.slave;
msg.payload.heartbeat = s.heartbeat;
node.status({fill:'green',shape:'dot',text: msg.payload.rows.length + ' points'});
return msg;

// Stamp the segment this frame physically arrived on, BEFORE it reaches the
// shared decode chain and the blacklist tap. The Nano's {t:'r',id} carries
// only the unit address, which Modbus guarantees unique per bus - the tag is
// what lets processReadResult resolve it against the right slave.
//
// Top-level msg property, not msg.payload.bus_id: payload here is still the
// raw serial string; the json node downstream rewrites payload but leaves
// other msg properties alone, so the tag survives to the tap.
msg.bus_id = 'bus2';

// Liveness stamp for the silence watchdog. A Node-RED `trigger` fires ONCE
// and then needs an input to re-arm, so a Nano that missed the single resend
// would stay dark forever; a timestamp plus a periodic check keeps retrying
// for as long as this segment is quiet.
flow.set('bus2_last_frame_ms', Date.now());
return msg;

const { createStore, buildNanoJobMessage } = global.get('busductConfigService');

// WHICH RS-485 SEGMENT THIS PIPELINE SERVES.
// A literal, not env.get(): function nodes have no per-node environment - env
// resolves from the enclosing group, then the tab - and both Send Nano Job
// nodes live on this same tab, so an env var could never differ between them.
const MY_BUS = 'bus2';

if (msg.busId && msg.busId !== MY_BUS) {
  return null;   // a resend addressed to the other segment's Nano
}

const store = createStore();
const excludeSlaveIds = global.get('busduct_blacklist_exclude') || [];   // Slice 9
const result = buildNanoJobMessage(store, { excludeSlaveIds, busId: MY_BUS });
if (result.error) {
  node.warn('Nano job compile failed for ' + MY_BUS + ': ' + result.error);
  node.status({ fill: 'red', shape: 'ring', text: MY_BUS + ': ' + result.error });
  return null;
}
node.status({ fill: 'green', shape: 'dot', text: MY_BUS + ': ' + result.job.read[0] + ' slave(s) @ ' + new Date().toLocaleTimeString() });
msg.payload = result.job;
return msg;

// bus1's silence watchdog resends the LEGACY read job; bus2 has no legacy
// pipeline, so it resends the compiled job for its own segment. A Nano
// that rebooted (watchdog, brown-out, USB re-enumeration) polls nothing
// until it is handed a job again - this is what hands it back, and it
// keeps retrying for as long as the segment stays quiet.
const SILENCE_MS = 30000;    // no frame for this long -> resend
const RETRY_MS = 30000;      // ...but no more often than this
const now = Date.now();
const last = flow.get('bus2_last_frame_ms') || 0;

if (last && (now - last) < SILENCE_MS) {
  node.status({ fill: 'green', shape: 'dot', text: 'bus2 live' });
  return null;
}

const lastResend = context.get('lastResendMs') || 0;
if ((now - lastResend) < RETRY_MS) return null;
context.set('lastResendMs', now);

const quietFor = last ? Math.round((now - last) / 1000) + 's' : 'since boot';
node.warn('bus2 silent (' + quietFor + '), resending its job');
node.status({ fill: 'red', shape: 'ring', text: 'bus2 silent ' + quietFor });
return { payload: 'serial-silence', busId: 'bus2' };

// Thin wrapper over busductConfigService.wifi (src/network/wifi.js).
//
// THE PASSPHRASE STOPS HERE. It is taken off the incoming msg, handed to the
// library (which puts it on the helper's stdin, never argv) and never written
// to context, a global, the audit trail, a debug node or the cloud. Note the
// deliberate absence of any node.warn/node.log carrying msg.payload.
const svc = global.get('busductConfigService');
if (!svc || !svc.wifi) {
  node.error('busductConfigService.wifi not loaded - RESTART Node-RED (a Deploy does not re-require it)');
  return { payload: { error: 'Wi-Fi support not loaded on this panel. Restart Node-RED.' } };
}

const action = msg.payload && msg.payload.action;

if (action === 'connect') {
  const { ssid, passphrase, open } = msg.payload;
  svc.wifi.connect(ssid, passphrase, { open: !!open }).then((r) => {
    if (r.error) { node.send({ payload: { error: r.error } }); return; }
    node.status({ fill: 'green', shape: 'dot', text: 'joined ' + r.connected });
    // Re-read the real state rather than trusting the request - the operator
    // should see what the panel is actually on, not what they asked for.
    svc.wifi.status().then((s) => node.send({
      payload: { success: 'Connected to ' + r.connected, active: s.active || [] }
    }));
  });
  return null;
}

// default: scan (also used by the boot inject)
svc.wifi.scan().then((r) => {
  if (r.error) { node.send({ payload: { error: r.error } }); return; }
  svc.wifi.status().then((s) => node.send({
    payload: { networks: r.networks, active: s.active || [] }
  }));
});
return null;
